@once
<style>
.manager-page{--eco:#1f9254;--ink:#1c2634}.manager-heading{margin-bottom:1.7rem}.manager-heading h1{font-size:1.8rem;font-weight:700;letter-spacing:-.04em;margin:.2rem 0}.manager-heading p{margin:0;color:#738091}.eyebrow{font-size:.68rem;color:var(--eco);font-weight:700;letter-spacing:.11em}.manager-add{padding:.68rem 1rem;border-radius:.55rem;font-weight:600}.manager-add svg{width:17px;vertical-align:-3px;margin-right:.25rem}.metric-card{border:1px solid #e7ebf0;background:#fff;border-radius:.75rem;padding:1.1rem;display:flex;gap:.85rem;align-items:center;transition:.2s;color:var(--ink)}.metric-card:hover,.metric-card.active-filter{transform:translateY(-2px);border-color:#8dcca9;box-shadow:0 7px 18px rgba(31,146,84,.09)}.metric-card small,.metric-card em{display:block;color:#7b8794;font-style:normal;font-size:.73rem}.metric-card strong{display:block;font-size:1.5rem;line-height:1.25}.metric-icon{height:43px;width:43px;border-radius:.65rem;display:grid;place-items:center}.metric-icon svg{width:19px}.green{background:#e8f7ee;color:#1f9254}.amber{background:#fff5de;color:#dc9416}.blue{background:#eaf2ff;color:#3976d5}.purple{background:#f1ebff;color:#8562ca}.manager-table-card{border:0;border-radius:.8rem;box-shadow:0 2px 12px rgba(28,38,52,.05);overflow:hidden}.table-toolbar{padding:1.1rem 1.25rem;display:flex;gap:.8rem;justify-content:space-between;border-bottom:1px solid #edf0f3}.search-box{border:1px solid #dce2e8;border-radius:.5rem;padding:0 .65rem;display:flex;align-items:center;width:min(370px,100%)}.search-box svg{width:17px;color:#8d98a5}.search-box input{border:0;outline:0;padding:.62rem .5rem;width:100%;background:transparent}.toolbar-actions{display:flex;gap:.55rem}.toolbar-actions .form-select{width:130px}.toolbar-actions svg{width:15px;vertical-align:-3px}.manager-table th{background:#f9fafb;text-transform:uppercase;font-size:.68rem;letter-spacing:.05em;color:#758192;border:0;padding:1rem 1.25rem}.manager-table td{padding:1rem 1.25rem;vertical-align:middle;border-color:#eff1f3}.entity{display:flex;align-items:center;gap:.7rem}.entity-avatar{display:grid;place-items:center;width:36px;height:36px;border-radius:.55rem;color:#fff;font-weight:700}.entity strong,.entity small{display:block}.entity small,.muted-cell{color:#8792a0;font-size:.78rem;margin-top:.1rem}.count-pill{background:#f1f5f3;color:#507060;padding:.3rem .55rem;border-radius:2rem;font-size:.75rem;font-weight:600}.status-dot{font-size:.76rem;font-weight:600}.status-dot:before{content:'';display:inline-block;height:7px;width:7px;border-radius:50%;background:#1f9254;margin-right:.35rem}.status-dot.inactive:before{background:#a4adb8}.star-toggle{border:0;background:transparent;color:#c1c7ce;padding:.25rem}.star-toggle.is-featured{color:#efa62c}.star-toggle svg{width:18px}.table-action svg{width:17px}.empty-state{text-align:center;padding:3.5rem;color:#7c8794}.empty-state svg{width:28px}.modal-content{border:0;border-radius:.8rem}.modal-header,.modal-footer{border-color:#edf0f3}.form-label{font-weight:600;font-size:.82rem}.modal .form-control,.modal .form-select{padding:.65rem}.user-avatar{width:38px;height:38px;border-radius:50%;object-fit:cover}.role-pill{background:#edf5ff;color:#3b75c7;border-radius:2rem;padding:.28rem .6rem;font-size:.73rem;font-weight:600}.table-image{width:43px;height:43px;border-radius:.55rem;object-fit:cover;background:#f2f5f3}.price-cell{font-weight:700}.stock-good{color:#168547;font-weight:600;font-size:.78rem}.stock-low{color:#c77a15;font-weight:600;font-size:.78rem}@media(max-width:767px){.table-toolbar{flex-direction:column}.toolbar-actions .form-select{width:auto}.manager-table th,.manager-table td{padding:.85rem}.manager-heading h1{font-size:1.55rem}}
</style>
@endonce
